import{_ as r}from"./chunks/directory-information-users.By73wc6q.js";import{_ as i,H as o,f as a,i as t}from"./chunks/framework.B3xCVCEH.js";const n="/docs/assets/directory-copy-link.C_KnL6y6.png",s="/docs/assets/directory-shareable-link.BUI7Gjx7.png",k=JSON.parse('{"title":"Managing Users and Sharing","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/directory-sharing/index.md","filePath":"authoring/directory-sharing/README.md"}'),l={name:"authoring/directory-sharing/index.md"};function m(h,e,g,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="managing-users-and-sharing" tabindex="-1">Managing Users and Sharing <a class="header-anchor" href="#managing-users-and-sharing" aria-label="Permalink to &quot;Managing Users and Sharing&quot;">​</a></h1><p>Directories, Frameworks, and Resources can be shared with other users either by sharing a link to the item or by adding owners and readers (with Admin or View privileges) to the item.</p><p>You can only manage users on an item if you are an owner (listed as <em>Admin</em>) for the item.</p><h2 id="sharing-a-link-to-a-directory-or-framework" tabindex="-1">Sharing a Link to a Directory or Framework <a class="header-anchor" href="#sharing-a-link-to-a-directory-or-framework" aria-label="Permalink to &quot;Sharing a Link to a Directory or Framework&quot;">​</a></h2><p>To copy a link to a directory or framework:</p><ul><li>Click on the name of the item to show its Information on the right side panel.</li><li>In the <em><strong>Details</strong></em> section of the <em><strong>Information panel</strong></em>, click on <em><strong>copy link</strong></em><ul><li>This copies the shareable link to your clipboard</li></ul></li></ul><p>This option offers a method for sharing directories, given that exporting directories is not available at this time.</p><p><img src="'+n+'" alt="Directory Management - Directories Copy Link"></p><h2 id="managing-users-for-an-item" tabindex="-1">Managing Users for an Item <a class="header-anchor" href="#managing-users-for-an-item" aria-label="Permalink to &quot;Managing Users for an Item&quot;">​</a></h2><p>To control who can view+edit a directory, framework, or resource:</p><ul><li>Click on the item to show it in the <em><strong>Information Panel</strong></em>.</li><li>In the <em><strong>Users</strong></em> section of the <em><strong>Information Panel</strong></em>, click on <em><strong>manage users and privacy</strong></em>.</li></ul><p><img src="'+r+'" alt="Directory Management - Directories Shareable Link"></p><p>A dialogue window shows options for adding Users or Groups to the item. You can:</p><ul><li>View the current list of users with privileges (<em>Admin</em> or <em>View</em>)</li><li>Add new users or organizations</li><li>Delete current users or organizations</li></ul><p>The dialogue has an option to set the item as <em><strong>Public</strong></em> or <em><strong>Private</strong></em></p><ul><li><strong>Public</strong> items will be viewable by all users <ul><li>Public frameworks can be exported when opened</li></ul></li></ul><p>For directories and frameworks, a shareable link shows at the top of the window and provides a button to copy the link to your clipboard. This option offers a method for sharing directories, given that exporting directories is not available at this time.</p><p><img src="'+s+'" alt="Directory Management - Directories Shareable Link"></p>',18)])])}const w=i(l,[["render",m]]);export{k as __pageData,w as default};
